unsigned int custom_hash(const char *input) {
    unsigned int hash = 5381;
    int c;
    while ((c = *input++)) {
        hash = ((hash << 5) + hash) + c;
    }
    return hash;
}

// HMAC using custom_hash with secret as key
void hmac_compute(const char *data, const char *key, unsigned int *result) {
    // Inner hash with XOR 0x36
    unsigned int int_hash = 5381;
    unsigned int hkey_hash = 5381;

    for (int i = 0; key[i]; i++)
        int_hash = ((int_hash << 5) + int_hash) + (key[i] ^ 0x36);

    for (int i = 0; data[i]; i++)
        int_hash = ((int_hash << 5) + int_hash) + data[i];

    // Outer hash with XOR 0x5c
    unsigned int out_hash = 5381;
    for (int i = 0; key[i]; i++)
        out_hash = ((out_hash << 5) + out_hash) + (key[i] ^ 0x5c);

    out_hash = ((out_hash << 5) + out_hash) + int_hash;

    *result = out_hash;
}

