#include <iostream>
#include <fstream>
#include <cmath>
#include <vector>
#include <random>

using namespace std;

// Target density function f(x) = exp(-x^2/2) * (1 + sin(2x)^2)
double target_density(double x) {
    return exp(-x*x/2.0) * (1.0 + pow(sin(2.0*x), 2.0));
}

// Trapezoidal rule for numerical integration
void trapezoidal_integration(double &Z, double &I2, double a, double b, int N) {
    double h = (b - a) / N;
    Z = 0.5 * (target_density(a) + target_density(b));
    I2 = 0.5 * (a*a * target_density(a) + b*b * target_density(b));

    for (int i = 1; i < N; i++) {
        double x = a + i * h;
        Z += target_density(x);
        I2 += x*x * target_density(x);
    }

    Z *= h;
    I2 *= h;
}

int main() {
    const int N = 10000;  // Trapezoidal rule intervals
    const double a = -10.0;
    const double b = 10.0;
    const int num_samples = 100000;
    const int burn_in = 10000;
    const double sigma = 1.0;  // Proposal standard deviation
    const double x0 = 0.0;  // Start location

    // Compute normalization constant and second moment
    double Z, I2;
    trapezoidal_integration(Z, I2, a, b, N);
    double V_exact = I2 / Z;

    cout << "Normalization constant Z = " << Z << endl;
    cout << "Second moment I2 = " << I2 << endl;
    cout << "Exact variance V_exact = " << V_exact << endl;

    // Metropolis-Hastings sampling
    vector<double> samples;
    samples.reserve(num_samples);

    random_device rd;
    mt19937 gen(rd());
    normal_distribution<> proposal(x0, sigma);
    double current_x = x0;

    for (int i = 0; i < num_samples; i++) {
        // Propose new state
        double proposed_x = proposal(gen);
        double log_alpha = log(target_density(proposed_x)) - log(target_density(current_x));

        // Accept or reject
        uniform_real_distribution<> uniform(0.0, 1.0);
        if (log(uniform(gen)) < log_alpha) {
            current_x = proposed_x;
        }

        // After burn-in, store sample
        if (i >= burn_in) {
            samples.push_back(current_x);
        }
    }

    // Calculate sample variance of post-burn-in samples
    double sum = 0.0;
    double sum_sq = 0.0;

    for (size_t i = 0; i < samples.size(); i++) {
        sum += samples[i];
        sum_sq += samples[i] * samples[i];
    }

    double V_mcmc = (sum_sq / samples.size()) - (sum * sum / (samples.size() * samples.size()));
    cout << "MCMC variance V_mcmc = " << V_mcmc << endl;

    // Write samples to CSV
