// littleEndianReader wraps byte slice for little-endian reading (Go 1.18 compatible)
type littleEndianReader struct {
	data []byte
	off  int
}

func (r *littleEndianReader) Uint16() (uint16, error) {
	if r.off+2 > len(r.data) {
		return 0, fmt.Errorf("out of bounds")
	}
	v := uint16(r.data[r.off]) | uint16(r.data[r.off+1])<<8
	r.off += 2
	return v, nil
}

func (r *littleEndianReader) Uint32() (uint32, error) {
	if r.off+4 > len(r.data) {
		return 0, fmt.Errorf("out of bounds")
	}
	v := uint32(r.data[r.off]) |
		uint32(r.data[r.off+1])<<8 |
		uint32(r.data[r.off+2])<<16 |
